// Asking DeArrow about videos and deciding what their tiles show: a queue of
// lookups (four at a time, in screen order), the branding answer per video,
// then the title and the thumbnail, with each improvement handed to the
// sweep. A random frame can take the thumbnail server tens of seconds to
// render, so YouTube's auto-generated start frame stands in until it does, as
// in the extension.
//
// Like SponsorBlock, a branding request names only the first four characters
// of the SHA-256 of a video id, and the answer holds every video under that
// prefix that has a submission: one request serves every video of the page
// under the same prefix. A video id is sent only where a frame of it is asked
// for, which names it anyway: the thumbnail server, and the random frame's
// time for a video nobody submitted anything for.
import sha256 from 'tiny-sha256';
import { configRead } from '../config.js';
import { fetchJsonWithTimeout } from '../fetch-timeout.js';
import {
  AUTOGENERATED_FRAMES,
  BACKGROUND_SLOTS,
  BLANK_THUMB,
  BRANDING_API,
  EARLY_FRAME_MS,
  FETCH_TIMEOUT_MS,
  MAX_CONCURRENT,
  RANDOM_FRAME_RETRIES_MS,
  THUMBNAIL_API
} from './constants.js';
import { videos, currentGeneration } from './state.js';
import { loadThumb } from './thumbs.js';
import { isTrusted, resolveTitle, crowdsourcedTitle } from './titles.js';
import { diagDeArrow, diagId } from '../speed/diag.js';

const DEBUG = false;
// A lookup that failed (offline, the server down) is asked again when a
// response shows the video after this long.
const RETRY_AFTER_MS = 60000;

// The videos waiting: the ones with a tile on screen first (`onScreen`, in
// screen order), then the rest in response order (`queue`), on at most
// BACKGROUND_SLOTS of the MAX_CONCURRENT lookups.
const onScreen = [];
const queue = [];
let active = 0;
let activeBackground = 0;
// Whether a sweep has found any tile on screen yet (see pump). For the life of
// the page: only the app's first page is laid out after its lookups start;
// later pages, and DeArrow switched back on, find their tiles laid out.
let screenSeen = false;
// Hash prefix -> the branding request in flight for it.
const prefixRequests = new Map();
// Called with the video when what its tiles should show changed (index.js).
let onChange = () => {};

/** Sets what runs (with the video) when a video's title or thumbnail changed. */
export function setChangeHandler(fn) {
  onChange = fn;
}

/** The first four characters of the SHA-256 of a video id: all a branding request names. */
export const prefixOf = (videoId) => sha256(videoId).substring(0, 4);

/** The thumbnail server's URL for the frame of `videoId` at `time` seconds. */
const thumbnailUrl = (videoId, time) => `${THUMBNAIL_API}?videoID=${videoId}&time=${time}`;

/**
 * Whether a video should be looked up now: not waiting or being looked up,
 * and either answered but decided under settings since changed (stale), or
 * never answered and its last failure (if any) RETRY_AFTER_MS ago.
 */
export const wantsLookup = (video) =>
  !video.queued && !video.looking && (video.fetched ? video.stale : Date.now() >= video.retryAt);

/**
 * The branding of every video with a submission under `prefix`: an object by
 * video id ({} for a 404, nothing under it), or null when the request failed.
 * Asked once while in flight, however many videos wait for it.
 */
function brandingByPrefix(prefix) {
  let request = prefixRequests.get(prefix);
  if (!request) {
    request = fetchJsonWithTimeout(`${BRANDING_API}/${prefix}`, FETCH_TIMEOUT_MS).then(
      (res) => {
        if (res.ok) return res.data && typeof res.data === 'object' ? res.data : {};
        return res.status === 404 ? {} : null;
      },
      (e) => {
        if (DEBUG) console.info('[DeArrow] Branding lookup failed for', prefix, e.message);
        return null;
      }
    );
    prefixRequests.set(prefix, request);
    request.then(() => prefixRequests.delete(prefix));
  }
  return request;
}

/**
 * Hands an answer to every video under its prefix still waiting for one, so
 * the videos queued behind need no request of their own. Only those: an
 * answer names about 170 videos, most of them never shown.
 */
function settlePrefix(prefix, answer) {
  videos.forEach((video, videoId) => {
    if (video.fetched || video.prefix !== prefix) return;
    const raw = answer[videoId];
    video.raw = raw && typeof raw === 'object' ? raw : null;
    video.fetched = true;
  });
}

/**
 * The random frame's time in seconds, from the server's random position and
 * the video's length, so the frame is the one other DeArrow users already had
 * rendered; null without them (offline), and the auto-generated frame stays.
 * A video nobody submitted anything for is not in the prefix answer: its
 * random time is asked for by its id, which the frame request names anyway
 * (a 404 there still carries it).
 */
async function randomFrameTime(videoId, video) {
  let info = video.raw && video.raw.randomTime != null ? video.raw : null;
  if (!info) {
    if (!video.randomInfo) {
      video.randomInfo = fetchJsonWithTimeout(
        `${BRANDING_API}?videoID=${videoId}`,
        FETCH_TIMEOUT_MS,
        { bodyOn: [404] }
      ).then(
        (res) => (res.data && typeof res.data === 'object' ? res.data : null),
        () => null
      );
    }
    info = await video.randomInfo;
  }
  const duration = (info && info.videoDuration) || video.duration;
  const randomTime = info ? info.randomTime : null;
  return duration && typeof randomTime === 'number' ? randomTime * duration : null;
}

/**
 * Decides the thumbnail, calling show(thumb, crowdsourced) with each improvement: a trusted
 * crowdsourced frame, or the fallback the settings pick (YouTube's own, a
 * blank, one of YouTube's auto-generated frames, or a random frame with the
 * start frame standing in until the server has rendered it).
 */
// TEMPORARY (speed/diag.js): a thumbnail download with its time and outcome.
async function timedThumb(kind, url, videoId) {
  const t0 = performance.now();
  const copy = await loadThumb(url, videoId);
  diagDeArrow(`thumb: id: ${diagId(videoId)}, kind: ${kind}, ms: ${Math.round(performance.now() - t0)}, got: ${!!copy}`);
  return copy;
}

async function resolveThumb(videoId, video, gen, show) {
  if (!configRead('dearrowCrowdThumbnails')) {
    show(null);
    return;
  }

  const custom = video.raw && Array.isArray(video.raw.thumbnails) ? video.raw.thumbnails[0] : null;
  if (isTrusted(custom) && typeof custom.timestamp === 'number') {
    // officialTime: the time is a submitted one, so the server makes the
    // frame now when it has none cached, instead of answering empty.
    const url = thumbnailUrl(videoId, custom.timestamp) + '&officialTime=true&generateNow=true';
    show(await timedThumb('crowd', url, videoId), true);
    return;
  }
  // The community voted for YouTube's own thumbnail.
  if (custom && custom.original && (custom.locked || custom.votes >= 0)) {
    show(null);
    return;
  }

  const fallback = configRead('dearrowThumbnailFallback');
  if (fallback === 'original') {
    show(null);
    return;
  }
  if (fallback === 'blank') {
    show(BLANK_THUMB + videoId);
    return;
  }

  // Start, middle or end; the start frame for the random frame's stand-in.
  const autogenerated = fallbackFrameUrl(videoId);
  const timeAt = performance.now();
  const time = fallback === 'random' ? await randomFrameTime(videoId, video) : null;
  if (fallback === 'random') {
    diagDeArrow(`random time: id: ${diagId(videoId)}, ms: ${Math.round(performance.now() - timeAt)}, ` +
      `asked by id: ${!(video.raw && video.raw.randomTime != null)}, time: ${time}`);
  }
  if (gen !== currentGeneration()) return;
  if (time === null) {
    show(await timedThumb('autogenerated', autogenerated, videoId));
    return;
  }

  const url = thumbnailUrl(videoId, time);
  const ready = await timedThumb('random', url + '&generateNow=true', videoId);
  if (ready) {
    show(ready);
    return;
  }
  show(await timedThumb('stand-in', autogenerated, videoId));
  // Not awaited: the lookup moves on to the next video meanwhile.
  /** Asks for the random frame again after the next delay, until it comes or the delays run out. */
  const retry = (delays) => {
    if (!delays.length) return;
    setTimeout(async () => {
      if (gen !== currentGeneration()) return;
      const later = await timedThumb(`random retry after ${delays[0]}ms`, url, videoId);
      if (later) show(later);
      else retry(delays.slice(1));
    }, delays[0]);
  };
  retry(RANDOM_FRAME_RETRIES_MS);
}

/**
 * Decides `video`'s title, then sets off deciding its thumbnail without
 * waiting for it: the lookup's slot goes to the next video once the title is
 * decided (a thumbnail took up to 2 s while a TV started the app). Output from
 * an older generation is dropped.
 */
async function resolve(videoId, video) {
  if (!configRead('enableDeArrow')) return;
  const gen = currentGeneration();
  const titleAt = performance.now();
  const title = await resolveTitle(video);
  diagDeArrow(`title: id: ${diagId(videoId)}, ms: ${Math.round(performance.now() - titleAt)}, changed: ${!!title}`);
  if (gen !== currentGeneration()) return;
  // Decided under the settings in use now.
  video.stale = false;
  video.title = title;
  // What the community submitted, as opposed to a random frame or formatting:
  // what the DeArrow badge marks (tiles.js).
  video.crowdTitle = !!title && !!crowdsourcedTitle(video);
  video.resolved = true;
  onChange(video);

  video.thumbDecided = false;
  resolveThumb(videoId, video, gen, (thumb, crowdsourced) => {
    if (gen !== currentGeneration()) return;
    video.thumbDecided = true;
    const changed = video.thumb !== thumb;
    video.thumb = thumb;
    video.crowdThumb = !!thumb && !!crowdsourced;
    if (changed) onChange(video);
  });
}

/**
 * YouTube's frame the Without a Crowdsourced Thumbnail setting falls back to
 * (Start, Middle or End; the Start frame stands in for the random one), or
 * null for Original and Blank.
 */
function fallbackFrameUrl(videoId) {
  const fallback = configRead('dearrowThumbnailFallback');
  if (fallback === 'original' || fallback === 'blank') return null;
  const frame = AUTOGENERATED_FRAMES[fallback] || AUTOGENERATED_FRAMES.start;
  return `https://i.ytimg.com/vi/${videoId}/${frame}.jpg`;
}

/**
 * Shows the fallback frame of a video whose answer is still out EARLY_FRAME_MS
 * into its lookup, so a slow server leaves no tile waiting for its picture;
 * the decision once the answer comes (resolveThumb) replaces it, with a
 * crowdsourced thumbnail if there is one. Returns the timer, for the answer
 * that comes in time to cancel.
 */
function showEarlyFrame(videoId, video) {
  const url = configRead('dearrowCrowdThumbnails') ? fallbackFrameUrl(videoId) : null;
  if (!url || video.thumb) return null;
  const gen = currentGeneration();
  return setTimeout(async () => {
    if (video.thumbDecided || gen !== currentGeneration()) return;
    const copy = await timedThumb('early', url, videoId);
    if (!copy || video.thumbDecided || video.thumb || gen !== currentGeneration()) return;
    video.thumb = copy;
    video.crowdThumb = false;
    onChange(video);
  }, EARLY_FRAME_MS);
}

/**
 * Starts drawing a video's fallback frame now, alongside its branding request
 * rather than after it: the answer (or the early frame) then finds it ready,
 * unless the answer brings a crowdsourced thumbnail instead.
 */
function prefetchFallback(videoId) {
  const url = configRead('dearrowCrowdThumbnails') ? fallbackFrameUrl(videoId) : null;
  if (url) loadThumb(url, videoId);
}

/**
 * Asks about one video (once its prefix answered), then decides what its tiles
 * show. `prefetch`: the video is (likely) on screen, so its fallback frame is
 * fetched while the answer is out.
 */
async function lookup(videoId, prefetch) {
  const video = videos.get(videoId);
  if (!video) return;
  video.queued = false;
  // Decided since it was queued (a tile asked again meanwhile).
  if (video.fetched && video.resolved && !video.stale) return;
  video.looking = true;
  const startedAt = performance.now();
  diagDeArrow(`lookup start: id: ${diagId(videoId)}, waited in queue: ${Math.round(startedAt - (video.diagQueuedAt || startedAt))}ms, ` +
    `active: ${active}, on screen: ${onScreen.length}, background: ${queue.length}, fetched: ${video.fetched}, stale: ${video.stale}, prefetch: ${!!prefetch}`);
  try {
    if (!video.fetched) {
      if (!video.prefix) video.prefix = prefixOf(videoId);
      if (prefetch) prefetchFallback(videoId);
      const early = showEarlyFrame(videoId, video);
      const askedAt = performance.now();
      const answer = await brandingByPrefix(video.prefix);
      clearTimeout(early);
      diagDeArrow(`branding: id: ${diagId(videoId)}, prefix: ${video.prefix}, ms: ${Math.round(performance.now() - askedAt)}, ` +
        `answer: ${answer ? 'ok' : 'failed'}, submission: ${!!(answer && answer[videoId])}`);
      // Wiped meanwhile (too many videos, or DeArrow off): nothing to write to.
      if (videos.get(videoId) !== video) return;
      if (answer) settlePrefix(video.prefix, answer);
      else video.retryAt = Date.now() + RETRY_AFTER_MS;
    }
    // Formatting the original title can still apply without an answer.
    await resolve(videoId, video);
    diagDeArrow(`lookup done: id: ${diagId(videoId)}, ms: ${Math.round(performance.now() - startedAt)}`);
  } finally {
    video.looking = false;
  }
}

/**
 * Starts waiting lookups until MAX_CONCURRENT run: the ones on screen first,
 * then the background ones on at most BACKGROUND_SLOTS, so a lookup for what
 * scrolling brings on screen never waits for the rest of the page.
 */
function pump() {
  while (active < MAX_CONCURRENT && configRead('enableDeArrow')) {
    let videoId;
    let background = false;
    if (onScreen.length) {
      videoId = onScreen.shift();
    } else if (queue.length && activeBackground < BACKGROUND_SLOTS) {
      videoId = queue.shift();
      background = true;
    } else {
      return;
    }
    active++;
    if (background) activeBackground++;
    /** One lookup done: start the next. */
    const next = () => {
      active--;
      if (background) activeBackground--;
      pump();
    };
    // Until a sweep has found any tile on screen (the app lays its first page
    // out a second or more after the response), the first lookups are the
    // first row's: they prefetch as the ones on screen do.
    lookup(videoId, !background || !screenSeen).then(next, next);
  }
}

/** Hashes a video for its lookup and marks it waiting. */
function markQueued(id, video) {
  // Hashed now, in screen order, so an answer can settle the videos queued behind.
  if (!video.prefix) video.prefix = prefixOf(id);
  video.queued = true;
  if (!video.diagQueuedAt) video.diagQueuedAt = performance.now();
}

/** Queues `ids` for a lookup in the background, in order, and starts what can start. */
export function queueLookups(ids) {
  for (let i = 0; i < ids.length; i++) {
    const video = videos.get(ids[i]);
    if (!video || video.queued) continue;
    markQueued(ids[i], video);
    queue.push(ids[i]);
  }
  pump();
}

/**
 * Puts the videos with a tile on screen (`ids`, in screen order) ahead of the
 * background: the ones waiting there, and the ones a lookup is due for
 * (wantsLookup). A background lookup already waiting for its answer fetches
 * its fallback frame now. Starts what can start.
 */
export function lookUpOnScreen(ids) {
  if (ids.length) screenSeen = true;
  for (let i = 0; i < ids.length; i++) {
    const video = videos.get(ids[i]);
    if (!video || onScreen.indexOf(ids[i]) !== -1) continue;
    if (video.looking) {
      // loadThumb takes the frame already asked for, if it is.
      if (!video.fetched) prefetchFallback(ids[i]);
      continue;
    }
    if (video.queued) {
      const at = queue.indexOf(ids[i]);
      if (at !== -1) queue.splice(at, 1);
    } else if (!wantsLookup(video)) {
      continue;
    }
    markQueued(ids[i], video);
    onScreen.push(ids[i]);
  }
  pump();
}

/** Empties the queues (lookups already running finish, their output dropped by generation). */
export function clearQueue() {
  for (const list of [onScreen, queue]) {
    for (let i = 0; i < list.length; i++) {
      const video = videos.get(list[i]);
      if (video) video.queued = false;
    }
    list.length = 0;
  }
}
